#!/usr/bin/env python3
"""Assert no workflow or dist config requests a retired GitHub runner label.

GitHub retires hosted runner images on a published schedule. A job pinned to a
retired label does not fail with a useful message: the runner is never assigned
and the job is cancelled a second after it starts, so every downstream job that
`needs` it is skipped and a release publishes nothing. That happened to this
repository's macOS arm build, which sat on `macos-14` while that image was
deprecated (#601 follow-up).

The gate reads the labels this repository can request from two places:

- `.github/workflows/*.yml`, where a literal label may appear in `runs-on` or in
  a quoted string such as `runs-on: macos-14`;
- `dist-workspace.toml`, where cargo-dist lets a target choose its runner in
  `[dist.github-custom-runners]`. The release workflow takes its matrix from
  `dist plan` at run time, so the label is not in the YAML at all and a scan of
  the workflows alone would miss it.

A label is retired here only when it is named in `RETIRED_RUNNERS` with the
first-party source that says so. Anything else is left alone: this gate exists
to catch a documented removal, not to guess.

Stdlib only. Exposes validate(root) -> list[str] for the regression tests.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
WORKFLOWS_REL = Path(".github/workflows")
DIST_CONFIG_REL = Path("dist-workspace.toml")

# label -> (deprecation source, note). Add an entry only after reading the
# first-party notice; a guess here red-builds every release for no reason.
RETIRED_RUNNERS = {
    "macos-14": (
        "https://github.com/actions/runner-images/issues/13518",
        "macOS 14 images are deprecated and unsupported from 2026-11-02; "
        "jobs on this label are cancelled without a runner. Use macos-15 or newer.",
    ),
    "macos-14-arm64": (
        "https://github.com/actions/runner-images/issues/13518",
        "macOS 14 images are deprecated and unsupported from 2026-11-02; "
        "jobs on this label are cancelled without a runner. Use macos-15 or newer.",
    ),
    "macos-14-large": (
        "https://github.com/actions/runner-images/issues/13518",
        "macOS 14 images are deprecated and unsupported from 2026-11-02; "
        "jobs on this label are cancelled without a runner. Use macos-15 or newer.",
    ),
    "macos-14-xlarge": (
        "https://github.com/actions/runner-images/issues/13518",
        "macOS 14 images are deprecated and unsupported from 2026-11-02; "
        "jobs on this label are cancelled without a runner. Use macos-15 or newer.",
    ),
}

# A target whose cargo-dist default is a retired image must pin a runner
# explicitly, because the matrix is generated by `dist plan` at run time and the
# retired label therefore never appears in the workflow YAML to be scanned.
REQUIRED_PINS = {
    "aarch64-apple-darwin": (
        "cargo-dist still defaults this target to the retired macos-14 image, so an "
        "explicit runner is required"
    ),
}

# A retired label only trips the gate as a whole token: `macos-14` must not
# match inside `macos-14-large` twice, and a comment may discuss the old label.
TOKEN_RE = re.compile(r"[A-Za-z0-9_.-]+")


def _strip_comment(line: str) -> str:
    quote: str | None = None
    for i, ch in enumerate(line):
        if quote:
            if ch == quote:
                quote = None
            continue
        if ch in "\"'":
            quote = ch
            continue
        if ch == "#":
            return line[:i]
    return line


def _labels_in(text: str) -> list[str]:
    return TOKEN_RE.findall(_strip_comment(text))


def _scan_workflows(root: Path) -> list[str]:
    problems: list[str] = []
    workflows = root / WORKFLOWS_REL
    if not workflows.is_dir():
        return problems
    for path in sorted(workflows.glob("*.yml")) + sorted(workflows.glob("*.yaml")):
        rel = path.relative_to(root)
        for number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
            for label in _labels_in(raw):
                retired = RETIRED_RUNNERS.get(label)
                if retired:
                    source, note = retired
                    problems.append(
                        f"{rel}:{number}: requests retired runner '{label}'. {note} ({source})"
                    )
    return problems


def _scan_dist_config(root: Path) -> list[str]:
    problems: list[str] = []
    path = root / DIST_CONFIG_REL
    if not path.is_file():
        for target, note in REQUIRED_PINS.items():
            problems.append(f"{DIST_CONFIG_REL}: missing, so {target} is unpinned — {note}.")
        return problems
    in_runners = False
    pinned: dict[str, str] = {}
    for number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        line = _strip_comment(raw)
        stripped = line.strip()
        if stripped.startswith("["):
            in_runners = stripped == "[dist.github-custom-runners]"
            continue
        if not in_runners or "=" not in line:
            continue
        target, value = line.split("=", 1)
        target = target.strip()
        label = value.strip().strip("\"'")
        pinned[target] = label
        retired = RETIRED_RUNNERS.get(label)
        if retired:
            source, note = retired
            problems.append(
                f"{DIST_CONFIG_REL}:{number}: {target} uses retired runner "
                f"'{label}'. {note} ({source})"
            )
    for target, note in REQUIRED_PINS.items():
        if target not in pinned:
            problems.append(
                f"{DIST_CONFIG_REL}: {target} has no runner pin — {note}. "
                "Add it under [dist.github-custom-runners]."
            )
    return problems


def validate(root: Path = ROOT) -> list[str]:
    """Return one message per retired runner label this repo still requests."""
    return _scan_workflows(root) + _scan_dist_config(root)


def main() -> int:
    problems = validate(ROOT)
    for problem in problems:
        print(problem, file=sys.stderr)
    if problems:
        print(f"{len(problems)} retired runner label(s) still requested.", file=sys.stderr)
        return 1
    print("No retired runner labels are requested.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
